#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Immersive

COMPONENT Scripting : 1

NavigationInfo {
  type "WALK"
  speed 4
}

Viewpoint {
  position 0 1.6 20
}

DEF BOX Transform {
  children Shape {
    geometry Box { }
  }
}

DEF REC Script {
  inputOutput SFFloat speed 0
  inputOutput SFFloat rate 60
  inputOutput SFInt32 frames 11

  url "ecmascript:
    function prepareEvents () { speed = Browser .currentSpeed; rate = Browser .currentFrameRate; frames = frames + 1; }
  "
}

